QVector<CalibrationModelRecord> originals;originals.append(CalibrationModelRecord::create(model("old",1,10),oldSetup,base.image()));originals.append(CalibrationModelRecord::create(model("old",2,20),oldSetup,base.image()).named("Named version"));originals.append(CalibrationModelRecord::adoptLegacy(model("old",3,30),oldSetup,"Legacy accepted"));ActiveCalibrationService global(path+".active-calibrations.json",p.project().id,[]{return true;});for(const auto& r:originals)global.save(r);global.activate("old",3,oldSetup);const auto originalSelection=global.remembered();QVector<QJsonObject> originalBytes;for(const auto& r:originals)originalBytes.append(r.encode());
