auto upSetup=oldSetup;upSetup.target.axes=AxisConvention::XRightYUp;auto upDependency=base.model().dependency();upDependency.calibrationId="up";upDependency.target=upSetup.target;auto upModel=math.teach(upDependency,{"teach",{scan.points()[0].pixel,upSetup.source},{scan.points()[1].pixel,upSetup.source},10});const auto upRecord=CalibrationModelRecord::create(upModel,upSetup,base.image());reject([&]{CalibrationModelRecord::mapLegacy(upRecord,w.calibrations().setup(ref),"Up",QDateTime::currentDateTimeUtc());});
IndependentCalibrationSession probe;IndependentCaptureRequest request;request.origin=SourceOrigin::CameraAcquired;request.camera=camera;request.setup=descriptor;IndependentCaptureBackend backend{[&]{return QVector<DeviceBinding>{camera.device};},[](const DeviceBinding&,const GeometryDescriptor&){return std::make_unique<Adapter>();}};check(probe.accept(IndependentCalibrationSession::run(probe.begin(request),backend)),"Fresh actual probe");w.calibrations().setOperational(camera.id,descriptor.id);w.calibrations().activate(ref,mapped[2].contentId(),probe);check(w.calibrations().snapshots({ref}).first().calibration.record.contentId()==mapped[2].contentId(),"Explicit mapped legacy activation after actual camera check");check(global.remembered()==originalSelection,"Scoped activation does not mutate legacy selection");
CalibrationService legacy(path+".calibrations.json");legacy.save(model("math-old",1,10));legacy.save(model("math-old",2,20));auto histories=w.legacyHistories();auto mathHistory=histories.value("Eski matematik • math-old");check(mathHistory.size()==2,"Raw legacy all versions found");reject([&]{w.calibrations().migrateLegacy(ref,mathHistory,1);});histories=w.legacyHistories();check(w.calibrations().migrateLegacy(ref,histories.value("Eski matematik • math-old"))==1,"Raw legacy retry reuses original prefix evidence");
p.bindSourceSetup(sourceId,ref.toJson());p.save();const RuntimeIdentity actor{"engineer",[](const QString&,ProductionAction){return true;}};RuntimeService runtime(path+".production",path+".calibrations.json",actor,{},[&](const Recipe& r){return w.forRecipe(r);},[&](const Recipe& r){return w.acquisition(r);});runtime.prepare(*p.activeRecipe(),dir.path());const auto lease=runtime.begin();const auto cycle=RuntimeService::execute(lease,{},{});check(cycle.state==ExecutionState::Done,"Real raw terminal for transfer");runtime.finish(lease.ticket,cycle);
