reject([&]{MeasurementProjectTransfer::copy(path,dir.filePath("missing-assets/copy.vfproject"),p.project().id);});check(!QFileInfo::exists(dir.filePath("missing-assets/copy.vfproject")),"Missing destination relative asset rejected before project commit");QFile extra(target+".production/events/unrelated.json");check(extra.open(QIODevice::WriteOnly),"Destination foreign evidence fixture");extra.write("{}");extra.close();reject([&]{MeasurementProjectTransfer::copy(path,target,p.project().id);});
